const { getUser } = require('./db');

// Format user for API response
function formatUser(user) {
  return {
    id: user.id,
    name: user.name,
    email: user.email.toLowerCase(),  // BUG: crashes when email is in profile or null
    role: user.role,
    displayName: `${user.name} <${user.email}>`,
  };
}

